  DIVIDER_unsigned <= unsigned(DIVIDER);

  
  Data_Type_Conversion_out1 <= "1111" WHEN DIVIDER_unsigned(7 DOWNTO 4) /= "0000" ELSE
      DIVIDER_unsigned(3 DOWNTO 0);

  enb <= clk_enable;

  rd_0_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        ramselektor_out1 <= to_unsigned(16#0#, 4);
      ELSIF enb = '1' THEN
        ramselektor_out1 <= ramselektor_out1_unsigned;
      END IF;
    END IF;
  END PROCESS rd_0_process;


  ramselektor_out1_unsigned <= unsigned(ramselektor_out1_1);

  CONTROLWORD_unsigned <= unsigned(CONTROLWORD);

  FKT1DATAFLOW_unsigned <= unsigned(FKT1DATAFLOW);

  FKT2RECOVERYTIME_unsigned <= unsigned(FKT2RECOVERYTIME);

  FKT4DATACLKSYNC_unsigned <= unsigned(FKT4DATACLKSYNC);

  FKT5TELEGRAMLEN_unsigned <= unsigned(FKT5TELEGRAMLEN);

  FKT6SYNCRESPONSE_unsigned <= unsigned(FKT6SYNCRESPONSE);

  FKT7EXTRASHIFT_signed <= signed(FKT7EXTRASHIFT);

  FKT7EXTRASHIFT_dtc <= unsigned(resize(FKT7EXTRASHIFT_signed, 16));

  ControlWordRAM_out1 <= to_unsigned(16#00#, 8);

  EndatControlRAM_out1 <= to_unsigned(16#01#, 8);

  FKT1_out1 <= to_unsigned(16#02#, 8);

  FKT2_out1 <= to_unsigned(16#03#, 8);

  FKT4_out1 <= to_unsigned(16#05#, 8);

  FKT5_out1 <= to_unsigned(16#06#, 8);

  FKT6_out1 <= to_unsigned(16#07#, 8);

  FKT7_out1 <= to_unsigned(16#08#, 8);

  Logical_Operator3_out1 <=  NOT CONTROLWORDRAW_out16;

  
  RAM_SELECTOR_out1 <= ControlWordRAM_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#0#, 4) ELSE
      EndatControlRAM_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#1#, 4) ELSE
      FKT1_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#2#, 4) ELSE
      FKT2_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#3#, 4) ELSE
      FKT4_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#4#, 4) ELSE
      FKT5_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#5#, 4) ELSE
      FKT6_out1 WHEN ramselektor_out1_unsigned = to_unsigned(16#6#, 4) ELSE
      FKT7_out1;

  Logical_Operator1_out1 <= Logical_Operator3_out1 AND Compare_To_Constant_out1;

  Logical_Operator2_out1 <=  NOT Logical_Operator1_out1;

  Logical_Operator_out1 <= Detect_Change_out1 AND Logical_Operator2_out1;

  Data_Type_Conversion4_out1 <= CONTROLWORDSTORED_out1;

  Data_Type_Conversion5_out1 <= CONTROLWORDSTORED_out2;

  Data_Type_Conversion6_out1 <= CONTROLWORDSTORED_out3;

  Data_Type_Conversion7_out1 <= CONTROLWORDSTORED_out4;

  Data_Type_Conversion8_out1 <= CONTROLWORDSTORED_out5;

  Data_Type_Conversion9_out1 <= CONTROLWORDSTORED_out6;

  y <= unsigned'(Data_Type_Conversion9_out1 & Data_Type_Conversion8_out1 & Data_Type_Conversion7_out1 & Data_Type_Conversion6_out1 & Data_Type_Conversion5_out1 & Data_Type_Conversion4_out1);

  rd_2_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        rd_2_reg <= (OTHERS => to_unsigned(16#00#, 6));
      ELSIF enb = '1' THEN
        rd_2_reg(0) <= y;
        rd_2_reg(1 TO 9) <= rd_2_reg(0 TO 8);
      END IF;
    END IF;
  END PROCESS rd_2_process;

  y_1 <= rd_2_reg(9);

  y_dtc <= resize(y_1, 16);

  
  RAM_SELECTOR1_out1 <= CONTROLWORD_unsigned WHEN ramselektor_out1_unsigned = to_unsigned(16#0#, 4) ELSE
      y_dtc WHEN ramselektor_out1_unsigned = to_unsigned(16#1#, 4) ELSE
      FKT1DATAFLOW_unsigned WHEN ramselektor_out1_unsigned = to_unsigned(16#2#, 4) ELSE
      FKT2RECOVERYTIME_unsigned WHEN ramselektor_out1_unsigned = to_unsigned(16#3#, 4) ELSE
